package com.carddemo.cbact01c.batch;

import com.carddemo.cbact01c.domain.Account;
import com.carddemo.cbact01c.repository.AccountRepository;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.JobExecutionListener;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.data.RepositoryItemReader;
import org.springframework.batch.item.data.builder.RepositoryItemReaderBuilder;
import org.springframework.batch.item.file.FlatFileItemWriter;
import org.springframework.batch.item.file.builder.FlatFileItemWriterBuilder;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.data.domain.Sort;
import org.springframework.transaction.PlatformTransactionManager;

import java.io.File;
import java.util.Locale;
import java.util.Map;

/**
 * Spring Batch configuration for the CBACT01C account file export job.
 *
 * <p>Maps the COBOL PROCEDURE DIVISION main flow (CBACT01C.cbl:140-160):
 * <pre>
 * L141  DISPLAY 'START OF EXECUTION'          → Spring Boot startup log
 * L142  PERFORM 0000-ACCTFILE-OPEN            → accountReader (ItemStream.open)
 * L143  PERFORM 2000-OUTFILE-OPEN             → outFileWriter (ItemStream.open via MultiFileItemWriter)
 * L144  PERFORM 3000-ARRFILE-OPEN             → arryFileWriter (ItemStream.open)
 * L145  PERFORM 4000-VBRFILE-OPEN             → vbrcFileWriter (ItemStream.open)
 * L147-154  PERFORM UNTIL END-OF-FILE         → chunk-oriented step (reader→processor→writer)
 * L156  PERFORM 9000-ACCTFILE-CLOSE           → step teardown (ItemStream.close)
 * L158  DISPLAY 'END OF EXECUTION'            → Spring Batch job completion log
 * </pre>
 */
@Configuration
public class AccountExportJobConfig {

    /** Output directory; override with {@code app.output-dir} property. */
    @Value("${app.output-dir:target/output}")
    private String outputDir;

    // ── Job ──────────────────────────────────────────────────────────────

    /**
     * Mirrors the CBACT01C top-level PROCEDURE DIVISION flow.
     * The {@link JobExecutionListener} ensures the output directory exists before
     * the step tries to open any {@link FlatFileItemWriter}.
     */
    @Bean
    public Job accountExportJob(JobRepository jobRepository, Step accountExportStep) {
        return new JobBuilder("accountExportJob", jobRepository)
                .listener(outputDirListener())
                .start(accountExportStep)
                .build();
    }

    // ── Step ─────────────────────────────────────────────────────────────

    /**
     * Chunk-oriented step: reads accounts in pages of 10, processes each, writes to 3 files.
     * Chunk size 10 gives restart granularity without excessive I/O overhead.
     */
    @Bean
    public Step accountExportStep(
            JobRepository jobRepository,
            PlatformTransactionManager txManager,
            RepositoryItemReader<Account> accountReader,
            AccountExportProcessor processor,
            MultiFileItemWriter multiFileItemWriter) {
        return new StepBuilder("accountExportStep", jobRepository)
                .<Account, AccountExportBundle>chunk(10, txManager)
                .reader(accountReader)
                .processor(processor)
                .writer(multiFileItemWriter)
                .build();
    }

    // ── Reader ───────────────────────────────────────────────────────────

    /**
     * Reads accounts sequentially ordered by ACCT-ID, mirroring the COBOL
     * {@code ACCESS MODE IS SEQUENTIAL} on the KSDS ACCTFILE.
     *
     * <p>COBOL: CBACT01C.cbl:29-33 — SELECT ACCTFILE-FILE with SEQUENTIAL access.
     * COBOL: CBACT01C.cbl:165-198 — 1000-ACCTFILE-GET-NEXT → READ ACCTFILE-FILE
     */
    @Bean
    public RepositoryItemReader<Account> accountReader(AccountRepository accountRepository) {
        return new RepositoryItemReaderBuilder<Account>()
                .name("accountReader")
                .repository(accountRepository)
                .methodName("findAll")
                .sorts(Map.of("acctId", Sort.Direction.ASC))
                .pageSize(10)
                .build();
    }

    // ── Writer ───────────────────────────────────────────────────────────

    /**
     * Composite writer for all three output files. Spring Batch auto-registers it
     * as an {@link org.springframework.batch.item.ItemStream} via the step builder.
     */
    @Bean
    public MultiFileItemWriter multiFileItemWriter() {
        return new MultiFileItemWriter(outFileWriter(), arryFileWriter(), vbrcFileWriter());
    }

    /**
     * OUTFILE: one flat record per account.
     * COBOL: CBACT01C.cbl:56-69 — FD OUT-FILE / 1350-WRITE-ACCT-RECORD
     *
     * <p>Format: ACCT-ID|ACTIVE|CURR-BAL|CREDIT-LIMIT|CASH-CREDIT-LIMIT|
     * OPEN-DATE|EXPIRATION-DATE|REISSUE-DATE(YYYYMMDD)|CYC-CREDIT|CYC-DEBIT|GROUP-ID
     */
    private FlatFileItemWriter<OutRecord> outFileWriter() {
        new File(outputDir).mkdirs();
        return new FlatFileItemWriterBuilder<OutRecord>()
                .name("outFileWriter")
                .resource(new FileSystemResource(outputDir + "/OUTFILE.txt"))
                .lineAggregator(r -> String.format(Locale.US, "%011d|%s|%14.2f|%14.2f|%14.2f|%s|%s|%s|%14.2f|%14.2f|%s",
                        r.acctId(),
                        r.activeStatus(),
                        r.currBal(),
                        r.creditLimit(),
                        r.cashCreditLimit(),
                        r.openDate(),
                        r.expirationDate(),
                        r.reissueDate(),
                        r.currCycCredit(),
                        r.currCycDebit(),
                        r.groupId() != null ? r.groupId() : ""))
                .build();
    }

    /**
     * ARRYFILE: one record per account with 5 balance/debit pairs.
     * COBOL: CBACT01C.cbl:71-78 — FD ARRY-FILE / 1450-WRITE-ARRY-RECORD
     *
     * <p>Format: ACCT-ID|BAL1|DEBIT1|BAL2|DEBIT2|BAL3|DEBIT3|BAL4|DEBIT4|BAL5|DEBIT5
     */
    private FlatFileItemWriter<ArrayRecord> arryFileWriter() {
        return new FlatFileItemWriterBuilder<ArrayRecord>()
                .name("arryFileWriter")
                .resource(new FileSystemResource(outputDir + "/ARRYFILE.txt"))
                .lineAggregator(r -> {
                    StringBuilder sb = new StringBuilder(String.format(Locale.US, "%011d", r.acctId()));
                    for (ArrayBalanceEntry e : r.balances()) {
                        sb.append(String.format(Locale.US, "|%14.2f|%14.2f", e.currBal(), e.currCycDebit()));
                    }
                    return sb.toString();
                })
                .build();
    }

    /**
     * VBRCFILE: two variable-length records per account (VBR1 then VBR2).
     * COBOL: CBACT01C.cbl:80-85 — FD VBRC-FILE (RECORDING MODE IS V)
     * / 1550-WRITE-VB1-RECORD + 1575-WRITE-VB2-RECORD
     */
    private FlatFileItemWriter<String> vbrcFileWriter() {
        return new FlatFileItemWriterBuilder<String>()
                .name("vbrcFileWriter")
                .resource(new FileSystemResource(outputDir + "/VBRCFILE.txt"))
                .lineAggregator(line -> line)
                .build();
    }

    // ── Listener ─────────────────────────────────────────────────────────

    /** Ensures output directory exists before any writer opens its file. */
    private JobExecutionListener outputDirListener() {
        return new JobExecutionListener() {
            @Override
            public void beforeJob(JobExecution jobExecution) {
                new File(outputDir).mkdirs();
            }
        };
    }
}

package com.carddemo.cbact01c.batch;

import com.carddemo.cbact01c.domain.Account;
import com.carddemo.cbact01c.service.DateConversionService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.util.List;

/**
 * Maps one {@link Account} (from ACCTFILE) into an {@link AccountExportBundle}
 * containing records for all three output files.
 *
 * <p>Mirrors the CBACT01C main loop processing:
 * <pre>
 * L170-213  1100-DISPLAY-ACCT-RECORD  → log.debug(account fields)
 * L215-240  1300-POPUL-ACCT-RECORD    → populate OutRecord
 *             L223-233  CALL 'COBDATFT' → dateConversionService.convertYyyyMmDdToYyyymmdd
 *             L236-238  IF ACCT-CURR-CYC-DEBIT = ZERO → MOVE 2525.00
 * L253-261  1400-POPUL-ARRAY-RECORD   → populate ArrayRecord (5 balance slots, entries 4-5 zero)
 * L276-285  1500-POPUL-VBRC-RECORD    → populate VbrRecord1 + VbrRecord2
 * </pre>
 */
@Component
public class AccountExportProcessor implements ItemProcessor<Account, AccountExportBundle> {

    private static final Logger log = LoggerFactory.getLogger(AccountExportProcessor.class);

    /**
     * Default substituted when ACCT-CURR-CYC-DEBIT = ZERO.
     * COBOL: CBACT01C.cbl:237 — MOVE 2525.00 TO OUT-ACCT-CURR-CYC-DEBIT
     */
    static final BigDecimal DEFAULT_CYC_DEBIT = new BigDecimal("2525.00");

    private final DateConversionService dateConversionService;

    public AccountExportProcessor(DateConversionService dateConversionService) {
        this.dateConversionService = dateConversionService;
    }

    @Override
    public AccountExportBundle process(Account account) {
        // COBOL: CBACT01C.cbl:200-213 — 1100-DISPLAY-ACCT-RECORD
        log.debug("ACCT-ID: {} ACCT-ACTIVE-STATUS: {} ACCT-CURR-BAL: {} ACCT-CREDIT-LIMIT: {} "
                + "ACCT-CASH-CREDIT-LIMIT: {} ACCT-OPEN-DATE: {} ACCT-EXPIRAION-DATE: {} "
                + "ACCT-REISSUE-DATE: {} ACCT-CURR-CYC-CREDIT: {} ACCT-CURR-CYC-DEBIT: {} ACCT-GROUP-ID: {}",
                account.getAcctId(), account.getActiveStatus(), account.getCurrBal(),
                account.getCreditLimit(), account.getCashCreditLimit(),
                account.getOpenDate(), account.getExpirationDate(), account.getReissueDate(),
                account.getCurrCycCredit(), account.getCurrCycDebit(), account.getGroupId());

        // COBOL: CBACT01C.cbl:215-240 — 1300-POPUL-ACCT-RECORD
        // CALL 'COBDATFT': CODATECN-TYPE='2' (YYYY-MM-DD in), CODATECN-OUTTYPE='2' (YYYYMMDD out)
        String formattedReissueDate = dateConversionService.convertYyyyMmDdToYyyymmdd(account.getReissueDate());

        // COBOL: CBACT01C.cbl:236-238 — IF ACCT-CURR-CYC-DEBIT EQUAL TO ZERO MOVE 2525.00
        BigDecimal outCycDebit = BigDecimal.ZERO.compareTo(account.getCurrCycDebit()) == 0
                ? DEFAULT_CYC_DEBIT
                : account.getCurrCycDebit();

        OutRecord outRecord = new OutRecord(
                account.getAcctId(),
                account.getActiveStatus(),
                account.getCurrBal(),
                account.getCreditLimit(),
                account.getCashCreditLimit(),
                account.getOpenDate(),
                account.getExpirationDate(),
                formattedReissueDate,
                account.getCurrCycCredit(),
                outCycDebit,
                account.getGroupId()
        );

        // COBOL: CBACT01C.cbl:253-261 — 1400-POPUL-ARRAY-RECORD
        // INITIALIZE ARR-ARRAY-REC sets all 5 slots to zero before populating entries 1-3
        List<ArrayBalanceEntry> entries = List.of(
                new ArrayBalanceEntry(account.getCurrBal(), new BigDecimal("1005.00")),         // entry 1
                new ArrayBalanceEntry(account.getCurrBal(), new BigDecimal("1525.00")),         // entry 2
                new ArrayBalanceEntry(new BigDecimal("-1025.00"), new BigDecimal("-2500.00")),  // entry 3
                new ArrayBalanceEntry(BigDecimal.ZERO, BigDecimal.ZERO),                        // entry 4 (INITIALIZE)
                new ArrayBalanceEntry(BigDecimal.ZERO, BigDecimal.ZERO)                         // entry 5 (INITIALIZE)
        );
        ArrayRecord arrayRecord = new ArrayRecord(account.getAcctId(), entries);

        // COBOL: CBACT01C.cbl:276-285 — 1500-POPUL-VBRC-RECORD
        // WS-ACCT-REISSUE-YYYY = first 4 chars of ACCT-REISSUE-DATE (YYYY-MM-DD → "YYYY")
        VbrRecord1 vbr1 = new VbrRecord1(account.getAcctId(), account.getActiveStatus());
        VbrRecord2 vbr2 = new VbrRecord2(
                account.getAcctId(),
                account.getCurrBal(),
                account.getCreditLimit(),
                extractYear(account.getReissueDate())
        );

        return new AccountExportBundle(outRecord, arrayRecord, vbr1, vbr2);
    }

    /**
     * Extracts the YYYY portion from a YYYY-MM-DD date string.
     * Mirrors WS-ACCT-REISSUE-YYYY PIC X(04) which is the first 4 chars of
     * the WS-ACCT-REISSUE-DATE group item (CBACT01C.cbl:131-136).
     */
    private String extractYear(String date) {
        if (date != null && date.length() >= 4) {
            return date.substring(0, 4);
        }
        return "    ";
    }
}

package com.carddemo.cbact01c.batch;

import org.springframework.batch.item.Chunk;
import org.springframework.batch.item.ExecutionContext;
import org.springframework.batch.item.ItemStream;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.file.FlatFileItemWriter;

import java.util.Locale;

import java.util.ArrayList;
import java.util.List;

/**
 * Writes an {@link AccountExportBundle} to three output files simultaneously,
 * mirroring the four WRITE statements in the CBACT01C main loop.
 *
 * <p>Per account the COBOL executes:
 * <pre>
 * L172  PERFORM 1350-WRITE-ACCT-RECORD → outFileWriter  (OUTFILE)
 * L174  PERFORM 1450-WRITE-ARRY-RECORD → arryFileWriter (ARRYFILE)
 * L177  PERFORM 1550-WRITE-VB1-RECORD  → vbrcFileWriter (VBRCFILE, VBR1 record, 12 bytes)
 * L178  PERFORM 1575-WRITE-VB2-RECORD  → vbrcFileWriter (VBRCFILE, VBR2 record, 39 bytes)
 * </pre>
 *
 * <p>Implements {@link ItemStream} so Spring Batch manages open/close of all
 * three {@link FlatFileItemWriter} instances through the standard step lifecycle
 * (replaces OPEN OUTPUT / CLOSE for OUT-FILE, ARRY-FILE, VBRC-FILE).
 */
public class MultiFileItemWriter implements ItemWriter<AccountExportBundle>, ItemStream {

    private final FlatFileItemWriter<OutRecord>   outWriter;
    private final FlatFileItemWriter<ArrayRecord> arryWriter;
    private final FlatFileItemWriter<String>      vbrcWriter;

    public MultiFileItemWriter(
            FlatFileItemWriter<OutRecord>   outWriter,
            FlatFileItemWriter<ArrayRecord> arryWriter,
            FlatFileItemWriter<String>      vbrcWriter) {
        this.outWriter  = outWriter;
        this.arryWriter = arryWriter;
        this.vbrcWriter = vbrcWriter;
    }

    /**
     * Distributes one chunk of bundles across all three output files.
     * VBR records are interleaved: VBR1 then VBR2 per account, matching
     * the COBOL write order in CBACT01C.cbl:177-178.
     */
    @Override
    public void write(Chunk<? extends AccountExportBundle> chunk) throws Exception {
        List<OutRecord>   outRecords  = new ArrayList<>();
        List<ArrayRecord> arryRecords = new ArrayList<>();
        List<String>      vbrcLines   = new ArrayList<>();

        for (AccountExportBundle bundle : chunk.getItems()) {
            outRecords.add(bundle.outRecord());
            arryRecords.add(bundle.arrayRecord());
            // COBOL: 1550-WRITE-VB1-RECORD then 1575-WRITE-VB2-RECORD per account
            vbrcLines.add(formatVbr1(bundle.vbrRecord1()));
            vbrcLines.add(formatVbr2(bundle.vbrRecord2()));
        }

        // COBOL: CBACT01C.cbl:242-251 — 1350-WRITE-ACCT-RECORD → WRITE OUT-ACCT-REC
        outWriter.write(new Chunk<>(outRecords));
        // COBOL: CBACT01C.cbl:263-274 — 1450-WRITE-ARRY-RECORD → WRITE ARR-ARRAY-REC
        arryWriter.write(new Chunk<>(arryRecords));
        // COBOL: CBACT01C.cbl:287-315 — 1550+1575-WRITE-VB*-RECORD → WRITE VBR-REC
        vbrcWriter.write(new Chunk<>(vbrcLines));
    }

    /**
     * Formats VBR1: type tag + ACCT-ID (11) + ACTIVE-STATUS (1) = 12 payload bytes.
     * COBOL: CBACT01C.cbl:287-300 — 1550-WRITE-VB1-RECORD (WS-RECD-LEN=12)
     */
    private String formatVbr1(VbrRecord1 r) {
        return String.format(Locale.US, "VBR1|%011d|%s", r.acctId(), r.activeStatus());
    }

    /**
     * Formats VBR2: type tag + ACCT-ID (11) + CURR-BAL + CREDIT-LIMIT + REISSUE-YYYY (4) = 39 payload bytes.
     * COBOL: CBACT01C.cbl:302-315 — 1575-WRITE-VB2-RECORD (WS-RECD-LEN=39)
     */
    private String formatVbr2(VbrRecord2 r) {
        return String.format(Locale.US, "VBR2|%011d|%14.2f|%14.2f|%4s",
                r.acctId(), r.currBal(), r.creditLimit(), r.reissueYear());
    }

    // ── ItemStream — delegates lifecycle to inner writers ────────────────

    /** Replaces OPEN OUTPUT OUT-FILE / ARRY-FILE / VBRC-FILE (CBACT01C.cbl:142-145) */
    @Override
    public void open(ExecutionContext executionContext) {
        outWriter.open(executionContext);
        arryWriter.open(executionContext);
        vbrcWriter.open(executionContext);
    }

    @Override
    public void update(ExecutionContext executionContext) {
        outWriter.update(executionContext);
        arryWriter.update(executionContext);
        vbrcWriter.update(executionContext);
    }

    /** Replaces CLOSE ACCTFILE (and implicit close of output files) in CBACT01C.cbl:156-160 */
    @Override
    public void close() {
        outWriter.close();
        arryWriter.close();
        vbrcWriter.close();
    }
}

package com.carddemo.cbact01c.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;

/**
 * Java equivalent of the Assembler call {@code CALL 'COBDATFT' USING CODATECN-REC}.
 *
 * <p>In CBACT01C the call is made with (see CODATECN.cpy):
 * <ul>
 *   <li>CODATECN-TYPE = '2'    → input format YYYY-MM-DD (YYYY-MM-DD-IN value)</li>
 *   <li>CODATECN-OUTTYPE = '2' → output format YYYYMMDD  (YYYYMMDD-OP value)</li>
 * </ul>
 *
 * <p>COBOL: CBACT01C.cbl:223-233 — 1300-POPUL-ACCT-RECORD
 * <pre>
 * L223   MOVE   ACCT-REISSUE-DATE  TO  CODATECN-INP-DATE
 * L225   MOVE   '2'                TO  CODATECN-TYPE
 * L226   MOVE   '2'                TO  CODATECN-OUTTYPE
 * L231   CALL 'COBDATFT'       USING CODATECN-REC
 * L233   MOVE   CODATECN-0UT-DATE  TO  OUT-ACCT-REISSUE-DATE
 * </pre>
 */
@Service
public class DateConversionService {

    private static final Logger log = LoggerFactory.getLogger(DateConversionService.class);

    private static final DateTimeFormatter INPUT_FMT  = DateTimeFormatter.ISO_LOCAL_DATE; // YYYY-MM-DD
    private static final DateTimeFormatter OUTPUT_FMT = DateTimeFormatter.BASIC_ISO_DATE; // YYYYMMDD
    private static final String            BLANK_DATE = "        ";                        // 8 spaces (CODATECN-0UT-DATE PIC X(20) portion)

    /**
     * Converts a YYYY-MM-DD date string to YYYYMMDD format.
     *
     * <p>Maps CODATECN-TYPE='2' (YYYY-MM-DD input) + CODATECN-OUTTYPE='2' (YYYYMMDD output).
     *
     * @param date input date in YYYY-MM-DD format; null or blank returns 8 spaces
     * @return date in YYYYMMDD format, or 8 spaces if input is invalid
     */
    public String convertYyyyMmDdToYyyymmdd(String date) {
        if (date == null || date.isBlank()) {
            return BLANK_DATE;
        }
        try {
            return LocalDate.parse(date, INPUT_FMT).format(OUTPUT_FMT);
        } catch (DateTimeParseException e) {
            log.warn("COBDATFT equivalent: invalid date '{}', returning blank", date);
            return BLANK_DATE;
        }
    }
}

package com.carddemo.cbact01c.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.math.BigDecimal;

/**
 * JPA entity that replaces the VSAM ACCTDAT file (ACCTFILE-FILE in CBACT01C).
 *
 * <p>Field layout follows copybook {@code app/cpy/CVACT01Y.cpy}
 * (ACCOUNT-RECORD, 300 bytes, keyed on ACCT-ID PIC 9(11)).
 * All financial fields use {@link BigDecimal} with scale 2.
 *
 * <p>COBOL: CBACT01C.cbl:29-33 (SELECT ACCTFILE-FILE) / CBACT01C.cbl:52-55 (FD ACCTFILE-FILE)
 */
@Entity
@Table(name = "accounts")
public class Account {

    /** ACCT-ID PIC 9(11) — primary key */
    @Id
    @Column(name = "acct_id")
    private Long acctId;

    /** ACCT-ACTIVE-STATUS PIC X(01) — 'Y' or 'N' */
    @Column(name = "active_status", length = 1, nullable = false)
    private String activeStatus;

    /** ACCT-CURR-BAL PIC S9(10)V99 */
    @Column(name = "curr_bal", precision = 12, scale = 2, nullable = false)
    private BigDecimal currBal;

    /** ACCT-CREDIT-LIMIT PIC S9(10)V99 */
    @Column(name = "credit_limit", precision = 12, scale = 2, nullable = false)
    private BigDecimal creditLimit;

    /** ACCT-CASH-CREDIT-LIMIT PIC S9(10)V99 */
    @Column(name = "cash_credit_limit", precision = 12, scale = 2, nullable = false)
    private BigDecimal cashCreditLimit;

    /** ACCT-OPEN-DATE PIC X(10) format YYYY-MM-DD */
    @Column(name = "open_date", length = 10)
    private String openDate;

    /**
     * ACCT-EXPIRAION-DATE PIC X(10) format YYYY-MM-DD
     * <p>Spelling "EXPIRAION" (missing 'T') is retained from COBOL source.
     */
    @Column(name = "expiration_date", length = 10)
    private String expirationDate;

    /** ACCT-REISSUE-DATE PIC X(10) format YYYY-MM-DD */
    @Column(name = "reissue_date", length = 10)
    private String reissueDate;

    /** ACCT-CURR-CYC-CREDIT PIC S9(10)V99 */
    @Column(name = "curr_cyc_credit", precision = 12, scale = 2, nullable = false)
    private BigDecimal currCycCredit;

    /** ACCT-CURR-CYC-DEBIT PIC S9(10)V99 COMP-3 */
    @Column(name = "curr_cyc_debit", precision = 12, scale = 2, nullable = false)
    private BigDecimal currCycDebit;

    /** ACCT-ADDR-ZIP PIC X(10) */
    @Column(name = "addr_zip", length = 10)
    private String addrZip;

    /** ACCT-GROUP-ID PIC X(10) */
    @Column(name = "group_id", length = 10)
    private String groupId;

    public Long getAcctId()                { return acctId; }
    public String getActiveStatus()        { return activeStatus; }
    public BigDecimal getCurrBal()         { return currBal; }
    public BigDecimal getCreditLimit()     { return creditLimit; }
    public BigDecimal getCashCreditLimit() { return cashCreditLimit; }
    public String getOpenDate()            { return openDate; }
    public String getExpirationDate()      { return expirationDate; }
    public String getReissueDate()         { return reissueDate; }
    public BigDecimal getCurrCycCredit()   { return currCycCredit; }
    public BigDecimal getCurrCycDebit()    { return currCycDebit; }
    public String getAddrZip()             { return addrZip; }
    public String getGroupId()             { return groupId; }

    public void setAcctId(Long acctId)                           { this.acctId = acctId; }
    public void setActiveStatus(String activeStatus)             { this.activeStatus = activeStatus; }
    public void setCurrBal(BigDecimal currBal)                   { this.currBal = currBal; }
    public void setCreditLimit(BigDecimal creditLimit)           { this.creditLimit = creditLimit; }
    public void setCashCreditLimit(BigDecimal cashCreditLimit)   { this.cashCreditLimit = cashCreditLimit; }
    public void setOpenDate(String openDate)                     { this.openDate = openDate; }
    public void setExpirationDate(String expirationDate)         { this.expirationDate = expirationDate; }
    public void setReissueDate(String reissueDate)               { this.reissueDate = reissueDate; }
    public void setCurrCycCredit(BigDecimal currCycCredit)       { this.currCycCredit = currCycCredit; }
    public void setCurrCycDebit(BigDecimal currCycDebit)         { this.currCycDebit = currCycDebit; }
    public void setAddrZip(String addrZip)                       { this.addrZip = addrZip; }
    public void setGroupId(String groupId)                       { this.groupId = groupId; }
}

package com.carddemo.cbact01c.repository;

import com.carddemo.cbact01c.domain.Account;
import org.springframework.data.jpa.repository.JpaRepository;

/**
